export const files: Record<string, string> = {
  ".env.example": "# Support Desk needs no environment variables or API keys.\n# Everything — tickets, replies, and canned responses — is stored locally\n# in your browser (localStorage). Nothing is sent to a server.\n",
  "README.md": "# Support Desk\n\nA customer support ticket queue: track tickets, reply in a message\nthread, and keep a small library of canned responses handy.\n\n## Features\n\n- Tickets with a subject, requester name/email, priority\n  (low/medium/high/urgent), status (open/pending/resolved/closed), and\n  an assignee picked from a small fixed team list.\n- A filterable, sortable ticket list — filter by status, priority, or\n  assignee, sort by last updated, newest, or priority — with pill stats\n  showing how many tickets are in each status at a glance.\n- Click a ticket to open its detail panel: the full message thread, a\n  reply box, and status/priority/assignee selectors.\n- A canned-replies library you can insert into a reply with one click,\n  and manage (add/edit/delete) from its own tab.\n\n## Demo data\n\nThis ships with a handful of realistic-looking demo tickets and canned\nreplies so the queue isn't empty the first time you open it (see\n`src/lib/seedData.ts`). **None of it is real** — it's fake names,\nemails, and messages. It's stored in `localStorage` exactly like\nanything you create yourself, so feel free to edit or delete every bit\nof it; it won't come back once you do (it's only ever seeded once, on\nthe very first load).\n\n## Getting started\n\n```bash\nnpm install\nnpm run dev\n```\n\n## Build\n\n```bash\nnpm run build\n```\n\n## Data storage\n\nTickets and canned replies are stored in your browser's `localStorage`.\nNothing leaves your device, and there is no account or sign-in.\n",
  "index.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Support Desk</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.tsx\"></script>\n  </body>\n</html>\n",
  "package.json": "{\n  \"name\": \"support-desk\",\n  \"private\": true,\n  \"version\": \"1.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"preview\": \"vite preview\"\n  },\n  \"dependencies\": {\n    \"lucide-react\": \"^0.417.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\"\n  },\n  \"devDependencies\": {\n    \"@types/react\": \"^18.3.3\",\n    \"@types/react-dom\": \"^18.3.0\",\n    \"@vitejs/plugin-react\": \"^4.3.1\",\n    \"autoprefixer\": \"^10.4.19\",\n    \"postcss\": \"^8.4.40\",\n    \"tailwindcss\": \"^3.4.7\",\n    \"typescript\": \"^5.5.4\",\n    \"vite\": \"^5.4.0\"\n  }\n}\n",
  "postcss.config.js": "export default {\n  plugins: {\n    tailwindcss: {},\n    autoprefixer: {},\n  },\n};\n",
  "src/App.tsx": "import { useEffect, useState } from \"react\";\nimport type { CannedReply, Priority, Ticket, TicketStatus } from \"./types\";\nimport { teamMemberName } from \"./types\";\nimport { loadCannedReplies, loadTickets, saveCannedReplies, saveTickets } from \"./lib/storage\";\nimport { NavBar, type NavView } from \"./components/NavBar\";\nimport { TicketList } from \"./components/TicketList\";\nimport { TicketDetailPanel } from \"./components/TicketDetailPanel\";\nimport { NewTicketModal } from \"./components/NewTicketModal\";\nimport { CannedRepliesPanel } from \"./components/CannedRepliesPanel\";\n\nexport default function App() {\n  const [tickets, setTickets] = useState<Ticket[]>(() => loadTickets());\n  const [cannedReplies, setCannedReplies] = useState<CannedReply[]>(() => loadCannedReplies());\n  const [view, setView] = useState<NavView>(\"tickets\");\n  const [openTicketId, setOpenTicketId] = useState<string | null>(null);\n  const [creatingTicket, setCreatingTicket] = useState(false);\n\n  useEffect(() => saveTickets(tickets), [tickets]);\n  useEffect(() => saveCannedReplies(cannedReplies), [cannedReplies]);\n\n  function patchTicket(id: string, patch: Partial<Ticket>) {\n    setTickets((prev) => prev.map((t) => (t.id === id ? { ...t, ...patch, updatedAt: Date.now() } : t)));\n  }\n\n  function createTicket(data: {\n    subject: string;\n    requesterName: string;\n    requesterEmail: string;\n    priority: Priority;\n    assigneeId: string | null;\n    firstMessage: string;\n  }) {\n    const now = Date.now();\n    const ticket: Ticket = {\n      id: crypto.randomUUID(),\n      subject: data.subject,\n      requesterName: data.requesterName,\n      requesterEmail: data.requesterEmail,\n      priority: data.priority,\n      status: \"open\",\n      assigneeId: data.assigneeId,\n      createdAt: now,\n      updatedAt: now,\n      messages: data.firstMessage\n        ? [{ id: crypto.randomUUID(), body: data.firstMessage, authorName: data.requesterName, fromCustomer: true, createdAt: now }]\n        : [],\n    };\n    setTickets((prev) => [ticket, ...prev]);\n    setCreatingTicket(false);\n    setOpenTicketId(ticket.id);\n  }\n\n  function deleteTicket(id: string) {\n    setTickets((prev) => prev.filter((t) => t.id !== id));\n    setOpenTicketId((current) => (current === id ? null : current));\n  }\n\n  function addReply(id: string, body: string) {\n    setTickets((prev) =>\n      prev.map((t) => {\n        if (t.id !== id) return t;\n        const authorName = teamMemberName(t.assigneeId) === \"Unassigned\" ? \"Support team\" : teamMemberName(t.assigneeId);\n        return {\n          ...t,\n          updatedAt: Date.now(),\n          messages: [\n            ...t.messages,\n            { id: crypto.randomUUID(), body, authorName, fromCustomer: false, createdAt: Date.now() },\n          ],\n        };\n      })\n    );\n  }\n\n  function addCannedReply(data: Omit<CannedReply, \"id\">) {\n    setCannedReplies((prev) => [...prev, { ...data, id: crypto.randomUUID() }]);\n  }\n  function updateCannedReply(id: string, data: Omit<CannedReply, \"id\">) {\n    setCannedReplies((prev) => prev.map((c) => (c.id === id ? { ...c, ...data } : c)));\n  }\n  function deleteCannedReply(id: string) {\n    setCannedReplies((prev) => prev.filter((c) => c.id !== id));\n  }\n\n  const openTicket = tickets.find((t) => t.id === openTicketId) ?? null;\n\n  return (\n    <div className=\"min-h-screen bg-gradient-to-b from-blue-50/50 via-slate-50 to-slate-50\">\n      <NavBar view={view} onNavigate={setView} onNewTicket={() => setCreatingTicket(true)} />\n\n      <main className=\"mx-auto max-w-6xl px-4 py-6\">\n        {view === \"tickets\" ? (\n          <TicketList\n            tickets={tickets}\n            onOpen={setOpenTicketId}\n            onStatusChange={(id, status) => patchTicket(id, { status })}\n            onPriorityChange={(id, priority) => patchTicket(id, { priority })}\n            onAssigneeChange={(id, assigneeId) => patchTicket(id, { assigneeId })}\n            onDelete={deleteTicket}\n            onNewTicket={() => setCreatingTicket(true)}\n          />\n        ) : (\n          <CannedRepliesPanel\n            replies={cannedReplies}\n            onAdd={addCannedReply}\n            onUpdate={updateCannedReply}\n            onDelete={deleteCannedReply}\n          />\n        )}\n      </main>\n\n      {creatingTicket && <NewTicketModal onCreate={createTicket} onClose={() => setCreatingTicket(false)} />}\n\n      {openTicket && (\n        <TicketDetailPanel\n          ticket={openTicket}\n          cannedReplies={cannedReplies}\n          onClose={() => setOpenTicketId(null)}\n          onStatusChange={(status: TicketStatus) => patchTicket(openTicket.id, { status })}\n          onPriorityChange={(priority: Priority) => patchTicket(openTicket.id, { priority })}\n          onAssigneeChange={(assigneeId) => patchTicket(openTicket.id, { assigneeId })}\n          onSubjectChange={(subject) => patchTicket(openTicket.id, { subject })}\n          onAddReply={(body) => addReply(openTicket.id, body)}\n          onDelete={() => deleteTicket(openTicket.id)}\n        />\n      )}\n    </div>\n  );\n}\n",
  "src/components/CannedRepliesPanel.tsx": "import { useState } from \"react\";\nimport { Pencil, Plus, Trash2 } from \"lucide-react\";\nimport type { CannedReply } from \"../types\";\n\ninterface Props {\n  replies: CannedReply[];\n  onAdd: (data: Omit<CannedReply, \"id\">) => void;\n  onUpdate: (id: string, data: Omit<CannedReply, \"id\">) => void;\n  onDelete: (id: string) => void;\n}\n\ninterface FormState {\n  title: string;\n  body: string;\n}\nconst EMPTY_FORM: FormState = { title: \"\", body: \"\" };\n\nfunction ReplyFields({ form, onChange }: { form: FormState; onChange: (f: FormState) => void }) {\n  return (\n    <div className=\"space-y-2\">\n      <input\n        autoFocus\n        value={form.title}\n        onChange={(e) => onChange({ ...form, title: e.target.value })}\n        placeholder=\"Title (e.g. Thanks for reaching out)\"\n        className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-blue-400\"\n      />\n      <textarea\n        value={form.body}\n        onChange={(e) => onChange({ ...form, body: e.target.value })}\n        placeholder=\"Reply text\"\n        rows={3}\n        className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-blue-400\"\n      />\n    </div>\n  );\n}\n\nexport function CannedRepliesPanel({ replies, onAdd, onUpdate, onDelete }: Props) {\n  const [adding, setAdding] = useState(false);\n  const [form, setForm] = useState<FormState>(EMPTY_FORM);\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [editForm, setEditForm] = useState<FormState>(EMPTY_FORM);\n  const [confirmingId, setConfirmingId] = useState<string | null>(null);\n  const [error, setError] = useState(\"\");\n\n  function submitAdd(e: React.FormEvent) {\n    e.preventDefault();\n    if (!form.title.trim() || !form.body.trim()) {\n      setError(\"A canned reply needs both a title and body.\");\n      return;\n    }\n    onAdd({ title: form.title.trim(), body: form.body.trim() });\n    setForm(EMPTY_FORM);\n    setAdding(false);\n    setError(\"\");\n  }\n\n  function startEdit(c: CannedReply) {\n    setEditingId(c.id);\n    setEditForm({ title: c.title, body: c.body });\n  }\n\n  function submitEdit(e: React.FormEvent) {\n    e.preventDefault();\n    if (!editingId) return;\n    if (!editForm.title.trim() || !editForm.body.trim()) {\n      setError(\"A canned reply needs both a title and body.\");\n      return;\n    }\n    onUpdate(editingId, { title: editForm.title.trim(), body: editForm.body.trim() });\n    setEditingId(null);\n    setError(\"\");\n  }\n\n  return (\n    <div className=\"mx-auto max-w-2xl\">\n      <div className=\"mb-4 flex items-center justify-between\">\n        <div>\n          <h2 className=\"text-lg font-semibold text-slate-900\">Canned replies</h2>\n          <p className=\"text-sm text-slate-500\">Reusable snippets you can insert into any ticket reply with one click.</p>\n        </div>\n        {!adding && (\n          <button\n            type=\"button\"\n            onClick={() => setAdding(true)}\n            className=\"flex shrink-0 items-center gap-1.5 rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\"\n          >\n            <Plus className=\"h-4 w-4\" /> Add reply\n          </button>\n        )}\n      </div>\n\n      {error && <p className=\"mb-3 text-sm text-red-600\">{error}</p>}\n\n      {adding && (\n        <form onSubmit={submitAdd} className=\"mb-4 space-y-2 rounded-xl border border-slate-200 p-4\">\n          <ReplyFields form={form} onChange={setForm} />\n          <div className=\"flex justify-end gap-2\">\n            <button\n              type=\"button\"\n              onClick={() => {\n                setAdding(false);\n                setForm(EMPTY_FORM);\n                setError(\"\");\n              }}\n              className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\"\n            >\n              Cancel\n            </button>\n            <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n              Save\n            </button>\n          </div>\n        </form>\n      )}\n\n      {replies.length === 0 && !adding ? (\n        <p className=\"rounded-xl border border-dashed border-slate-300 p-8 text-center text-sm text-slate-500\">\n          No canned replies yet. Add one to speed up ticket responses.\n        </p>\n      ) : (\n        <div className=\"space-y-2\">\n          {replies.map((c) => (\n            <div key={c.id} className=\"rounded-xl border border-slate-200 p-3\">\n              {editingId === c.id ? (\n                <form onSubmit={submitEdit} className=\"space-y-2\">\n                  <ReplyFields form={editForm} onChange={setEditForm} />\n                  <div className=\"flex justify-end gap-2\">\n                    <button type=\"button\" onClick={() => setEditingId(null)} className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\">\n                      Cancel\n                    </button>\n                    <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n                      Save\n                    </button>\n                  </div>\n                </form>\n              ) : (\n                <div className=\"flex items-start justify-between gap-2\">\n                  <div className=\"min-w-0\">\n                    <p className=\"text-sm font-medium text-slate-900\">{c.title}</p>\n                    <p className=\"mt-0.5 whitespace-pre-line text-xs text-slate-500\">{c.body}</p>\n                  </div>\n                  {confirmingId === c.id ? (\n                    <div className=\"flex shrink-0 items-center gap-1.5\">\n                      <button\n                        type=\"button\"\n                        onClick={() => {\n                          onDelete(c.id);\n                          setConfirmingId(null);\n                        }}\n                        className=\"text-xs font-medium text-red-600\"\n                      >\n                        Delete\n                      </button>\n                      <button type=\"button\" onClick={() => setConfirmingId(null)} className=\"text-xs text-slate-400\">\n                        Cancel\n                      </button>\n                    </div>\n                  ) : (\n                    <div className=\"flex shrink-0 items-center gap-0.5 text-slate-400\">\n                      <button type=\"button\" onClick={() => startEdit(c)} title=\"Edit\" className=\"rounded p-1.5 hover:bg-slate-100 hover:text-slate-700\">\n                        <Pencil className=\"h-3.5 w-3.5\" />\n                      </button>\n                      <button\n                        type=\"button\"\n                        onClick={() => setConfirmingId(c.id)}\n                        title=\"Delete\"\n                        className=\"rounded p-1.5 hover:bg-red-50 hover:text-red-600\"\n                      >\n                        <Trash2 className=\"h-3.5 w-3.5\" />\n                      </button>\n                    </div>\n                  )}\n                </div>\n              )}\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/components/NavBar.tsx": "import { Inbox, MessageSquareText, Plus } from \"lucide-react\";\n\nexport type NavView = \"tickets\" | \"canned\";\n\ninterface Props {\n  view: NavView;\n  onNavigate: (view: NavView) => void;\n  onNewTicket: () => void;\n}\n\nfunction navClass(active: boolean) {\n  return `flex items-center gap-1.5 rounded-full px-3 py-1.5 text-sm font-medium transition-colors ${\n    active ? \"bg-blue-600 text-white shadow-sm shadow-blue-500/30\" : \"text-slate-500 hover:bg-blue-50 hover:text-blue-700\"\n  }`;\n}\n\nexport function NavBar({ view, onNavigate, onNewTicket }: Props) {\n  return (\n    <header className=\"border-b border-blue-100/70 bg-white/90 backdrop-blur-sm\">\n      <div className=\"mx-auto flex max-w-6xl flex-wrap items-center gap-3 px-4 py-3.5\">\n        <h1 className=\"flex items-center gap-2 text-base font-bold tracking-tight text-slate-900\">\n          <span className=\"flex h-8 w-8 items-center justify-center rounded-xl bg-gradient-to-br from-blue-500 to-blue-700 text-white shadow-sm shadow-blue-500/30\">\n            <Inbox className=\"h-4 w-4\" />\n          </span>\n          Support Desk\n        </h1>\n        <nav className=\"flex items-center gap-1\">\n          <button type=\"button\" onClick={() => onNavigate(\"tickets\")} className={navClass(view === \"tickets\")}>\n            <Inbox className=\"h-3.5 w-3.5\" /> Tickets\n          </button>\n          <button type=\"button\" onClick={() => onNavigate(\"canned\")} className={navClass(view === \"canned\")}>\n            <MessageSquareText className=\"h-3.5 w-3.5\" /> Canned replies\n          </button>\n        </nav>\n        <button\n          type=\"button\"\n          onClick={onNewTicket}\n          className=\"ml-auto flex items-center gap-1.5 rounded-full bg-gradient-to-r from-blue-600 to-blue-700 px-4 py-2 text-sm font-semibold text-white shadow-sm shadow-blue-500/30 transition-all duration-150 hover:-translate-y-0.5 hover:shadow-md active:translate-y-0\"\n        >\n          <Plus className=\"h-4 w-4\" /> New ticket\n        </button>\n      </div>\n    </header>\n  );\n}\n",
  "src/components/NewTicketModal.tsx": "import { useState } from \"react\";\nimport { X } from \"lucide-react\";\nimport type { Priority } from \"../types\";\nimport { PRIORITIES, TEAM_MEMBERS } from \"../types\";\n\ninterface Props {\n  onCreate: (data: {\n    subject: string;\n    requesterName: string;\n    requesterEmail: string;\n    priority: Priority;\n    assigneeId: string | null;\n    firstMessage: string;\n  }) => void;\n  onClose: () => void;\n}\n\nexport function NewTicketModal({ onCreate, onClose }: Props) {\n  const [subject, setSubject] = useState(\"\");\n  const [requesterName, setRequesterName] = useState(\"\");\n  const [requesterEmail, setRequesterEmail] = useState(\"\");\n  const [priority, setPriority] = useState<Priority>(\"medium\");\n  const [assigneeId, setAssigneeId] = useState<string>(\"\");\n  const [firstMessage, setFirstMessage] = useState(\"\");\n  const [error, setError] = useState(\"\");\n\n  function handleSubmit(e: React.FormEvent) {\n    e.preventDefault();\n    if (!subject.trim()) {\n      setError(\"Give the ticket a subject.\");\n      return;\n    }\n    if (!requesterName.trim()) {\n      setError(\"The requester's name is required.\");\n      return;\n    }\n    onCreate({\n      subject: subject.trim(),\n      requesterName: requesterName.trim(),\n      requesterEmail: requesterEmail.trim(),\n      priority,\n      assigneeId: assigneeId || null,\n      firstMessage: firstMessage.trim(),\n    });\n  }\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4\" onClick={onClose}>\n      <div onClick={(e) => e.stopPropagation()} className=\"w-full max-w-md rounded-2xl bg-white p-6 shadow-xl\">\n        <div className=\"mb-4 flex items-center justify-between\">\n          <h2 className=\"text-lg font-semibold text-slate-900\">New ticket</h2>\n          <button type=\"button\" onClick={onClose} className=\"rounded-full p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-600\">\n            <X className=\"h-5 w-5\" />\n          </button>\n        </div>\n\n        <form onSubmit={handleSubmit} className=\"space-y-3\">\n          <input\n            autoFocus\n            value={subject}\n            onChange={(e) => setSubject(e.target.value)}\n            placeholder=\"Subject\"\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-blue-400\"\n          />\n          <div className=\"grid grid-cols-2 gap-2\">\n            <input\n              value={requesterName}\n              onChange={(e) => setRequesterName(e.target.value)}\n              placeholder=\"Requester name\"\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-blue-400\"\n            />\n            <input\n              value={requesterEmail}\n              onChange={(e) => setRequesterEmail(e.target.value)}\n              placeholder=\"Requester email\"\n              type=\"email\"\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-blue-400\"\n            />\n          </div>\n          <div className=\"grid grid-cols-2 gap-2\">\n            <select\n              value={priority}\n              onChange={(e) => setPriority(e.target.value as Priority)}\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm capitalize outline-none focus:border-blue-400\"\n            >\n              {PRIORITIES.map((p) => (\n                <option key={p} value={p}>\n                  {p}\n                </option>\n              ))}\n            </select>\n            <select\n              value={assigneeId}\n              onChange={(e) => setAssigneeId(e.target.value)}\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-blue-400\"\n            >\n              <option value=\"\">Unassigned</option>\n              {TEAM_MEMBERS.map((m) => (\n                <option key={m.id} value={m.id}>\n                  {m.name}\n                </option>\n              ))}\n            </select>\n          </div>\n          <textarea\n            value={firstMessage}\n            onChange={(e) => setFirstMessage(e.target.value)}\n            placeholder=\"What's the issue? (optional first message from the requester)\"\n            rows={3}\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-blue-400\"\n          />\n          {error && <p className=\"text-sm text-red-600\">{error}</p>}\n          <div className=\"flex justify-end gap-2 pt-1\">\n            <button type=\"button\" onClick={onClose} className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\">\n              Cancel\n            </button>\n            <button\n              type=\"submit\"\n              className=\"rounded-lg bg-gradient-to-r from-blue-600 to-blue-700 px-4 py-1.5 text-sm font-medium text-white shadow-sm shadow-blue-500/30\"\n            >\n              Create ticket\n            </button>\n          </div>\n        </form>\n      </div>\n    </div>\n  );\n}\n",
  "src/components/TicketDetailPanel.tsx": "import { useState } from \"react\";\nimport { Send, Trash2, X } from \"lucide-react\";\nimport type { CannedReply, Priority, Ticket, TicketStatus } from \"../types\";\nimport { PRIORITIES, TEAM_MEMBERS, TICKET_STATUSES, formatDateTime, teamMemberName } from \"../types\";\nimport { PRIORITY_STYLES, STATUS_STYLES } from \"./TicketList\";\n\ninterface Props {\n  ticket: Ticket;\n  cannedReplies: CannedReply[];\n  onClose: () => void;\n  onStatusChange: (status: TicketStatus) => void;\n  onPriorityChange: (priority: Priority) => void;\n  onAssigneeChange: (assigneeId: string | null) => void;\n  onSubjectChange: (subject: string) => void;\n  onAddReply: (body: string) => void;\n  onDelete: () => void;\n}\n\nexport function TicketDetailPanel({\n  ticket,\n  cannedReplies,\n  onClose,\n  onStatusChange,\n  onPriorityChange,\n  onAssigneeChange,\n  onSubjectChange,\n  onAddReply,\n  onDelete,\n}: Props) {\n  const [subject, setSubject] = useState(ticket.subject);\n  const [reply, setReply] = useState(\"\");\n  const [confirmingDelete, setConfirmingDelete] = useState(false);\n\n  function commitSubject() {\n    const trimmed = subject.trim();\n    if (trimmed && trimmed !== ticket.subject) onSubjectChange(trimmed);\n    else setSubject(ticket.subject);\n  }\n\n  function submitReply(e: React.FormEvent) {\n    e.preventDefault();\n    const trimmed = reply.trim();\n    if (!trimmed) return;\n    onAddReply(trimmed);\n    setReply(\"\");\n  }\n\n  function insertCanned(body: string) {\n    setReply((prev) => (prev.trim() ? `${prev}\\n\\n${body}` : body));\n  }\n\n  const thread = [...ticket.messages].sort((a, b) => a.createdAt - b.createdAt);\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex justify-end bg-black/40\" onClick={onClose}>\n      <div\n        onClick={(e) => e.stopPropagation()}\n        className=\"flex h-full w-full max-w-xl flex-col overflow-hidden bg-white shadow-xl\"\n      >\n        <div className=\"flex items-start justify-between gap-3 border-b border-slate-200 p-4\">\n          <div className=\"min-w-0 flex-1\">\n            <input\n              value={subject}\n              onChange={(e) => setSubject(e.target.value)}\n              onBlur={commitSubject}\n              className=\"w-full text-base font-semibold text-slate-900 outline-none\"\n            />\n            <p className=\"mt-0.5 truncate text-xs text-slate-500\">\n              {ticket.requesterName} · {ticket.requesterEmail}\n            </p>\n          </div>\n          <button type=\"button\" onClick={onClose} className=\"shrink-0 rounded-full p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-600\">\n            <X className=\"h-5 w-5\" />\n          </button>\n        </div>\n\n        <div className=\"grid grid-cols-3 gap-2 border-b border-slate-200 p-4\">\n          <div>\n            <label className=\"mb-1 block text-[11px] font-medium uppercase tracking-wide text-slate-400\">Status</label>\n            <select\n              value={ticket.status}\n              onChange={(e) => onStatusChange(e.target.value as TicketStatus)}\n              className={`w-full rounded-lg border-0 px-2 py-1.5 text-xs font-medium capitalize outline-none ${STATUS_STYLES[ticket.status]}`}\n            >\n              {TICKET_STATUSES.map((s) => (\n                <option key={s} value={s}>\n                  {s}\n                </option>\n              ))}\n            </select>\n          </div>\n          <div>\n            <label className=\"mb-1 block text-[11px] font-medium uppercase tracking-wide text-slate-400\">Priority</label>\n            <select\n              value={ticket.priority}\n              onChange={(e) => onPriorityChange(e.target.value as Priority)}\n              className={`w-full rounded-lg border-0 px-2 py-1.5 text-xs font-medium capitalize outline-none ${PRIORITY_STYLES[ticket.priority]}`}\n            >\n              {PRIORITIES.map((p) => (\n                <option key={p} value={p}>\n                  {p}\n                </option>\n              ))}\n            </select>\n          </div>\n          <div>\n            <label className=\"mb-1 block text-[11px] font-medium uppercase tracking-wide text-slate-400\">Assignee</label>\n            <select\n              value={ticket.assigneeId ?? \"\"}\n              onChange={(e) => onAssigneeChange(e.target.value || null)}\n              className=\"w-full rounded-lg border border-slate-200 px-2 py-1.5 text-xs outline-none focus:border-blue-400\"\n            >\n              <option value=\"\">Unassigned</option>\n              {TEAM_MEMBERS.map((m) => (\n                <option key={m.id} value={m.id}>\n                  {m.name}\n                </option>\n              ))}\n            </select>\n          </div>\n        </div>\n\n        <div className=\"flex-1 space-y-3 overflow-y-auto p-4\">\n          {thread.map((m) => (\n            <div key={m.id} className={`flex flex-col ${m.fromCustomer ? \"items-start\" : \"items-end\"}`}>\n              <div\n                className={`max-w-[85%] rounded-2xl px-3.5 py-2.5 text-sm ${\n                  m.fromCustomer ? \"rounded-tl-sm bg-slate-100 text-slate-800\" : \"rounded-tr-sm bg-blue-600 text-white\"\n                }`}\n              >\n                <p className=\"whitespace-pre-line\">{m.body}</p>\n              </div>\n              <p className=\"mt-1 px-1 text-[11px] text-slate-400\">\n                {m.authorName} · {formatDateTime(m.createdAt)}\n              </p>\n            </div>\n          ))}\n          {thread.length === 0 && <p className=\"text-sm text-slate-400\">No messages yet.</p>}\n        </div>\n\n        {cannedReplies.length > 0 && (\n          <div className=\"flex gap-1.5 overflow-x-auto border-t border-slate-100 px-4 py-2\">\n            {cannedReplies.map((c) => (\n              <button\n                key={c.id}\n                type=\"button\"\n                onClick={() => insertCanned(c.body)}\n                title={c.body}\n                className=\"shrink-0 rounded-full border border-blue-200 bg-blue-50 px-3 py-1 text-xs font-medium text-blue-700 hover:bg-blue-100\"\n              >\n                {c.title}\n              </button>\n            ))}\n          </div>\n        )}\n\n        <form onSubmit={submitReply} className=\"border-t border-slate-200 p-4\">\n          <textarea\n            value={reply}\n            onChange={(e) => setReply(e.target.value)}\n            placeholder={`Reply as ${teamMemberName(ticket.assigneeId) === \"Unassigned\" ? \"Support team\" : teamMemberName(ticket.assigneeId)}...`}\n            rows={3}\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-blue-400\"\n          />\n          <div className=\"mt-2 flex items-center justify-between\">\n            {confirmingDelete ? (\n              <div className=\"flex items-center gap-2\">\n                <span className=\"text-xs text-slate-500\">Delete this ticket?</span>\n                <button type=\"button\" onClick={onDelete} className=\"text-xs font-medium text-red-600\">\n                  Delete\n                </button>\n                <button type=\"button\" onClick={() => setConfirmingDelete(false)} className=\"text-xs text-slate-400\">\n                  Cancel\n                </button>\n              </div>\n            ) : (\n              <button\n                type=\"button\"\n                onClick={() => setConfirmingDelete(true)}\n                className=\"flex items-center gap-1.5 text-xs text-red-600 hover:text-red-700\"\n              >\n                <Trash2 className=\"h-3.5 w-3.5\" /> Delete ticket\n              </button>\n            )}\n            <button\n              type=\"submit\"\n              disabled={!reply.trim()}\n              className=\"flex items-center gap-1.5 rounded-lg bg-gradient-to-r from-blue-600 to-blue-700 px-4 py-2 text-sm font-semibold text-white shadow-sm shadow-blue-500/30 disabled:opacity-40\"\n            >\n              <Send className=\"h-3.5 w-3.5\" /> Send reply\n            </button>\n          </div>\n        </form>\n      </div>\n    </div>\n  );\n}\n",
  "src/components/TicketList.tsx": "import { useMemo, useState } from \"react\";\nimport { Inbox, Trash2 } from \"lucide-react\";\nimport type { Priority, SortKey, Ticket, TicketStatus } from \"../types\";\nimport { PRIORITIES, SORT_KEYS, TEAM_MEMBERS, TICKET_STATUSES, formatDateTime, priorityRank } from \"../types\";\n\ninterface Props {\n  tickets: Ticket[];\n  onOpen: (id: string) => void;\n  onStatusChange: (id: string, status: TicketStatus) => void;\n  onPriorityChange: (id: string, priority: Priority) => void;\n  onAssigneeChange: (id: string, assigneeId: string | null) => void;\n  onDelete: (id: string) => void;\n  onNewTicket: () => void;\n}\n\nexport const STATUS_STYLES: Record<TicketStatus, string> = {\n  open: \"bg-blue-100 text-blue-700\",\n  pending: \"bg-amber-100 text-amber-700\",\n  resolved: \"bg-emerald-100 text-emerald-700\",\n  closed: \"bg-slate-100 text-slate-600\",\n};\n\nexport const PRIORITY_STYLES: Record<Priority, string> = {\n  low: \"bg-slate-100 text-slate-600\",\n  medium: \"bg-blue-100 text-blue-700\",\n  high: \"bg-amber-100 text-amber-700\",\n  urgent: \"bg-red-100 text-red-700\",\n};\n\nconst SORT_LABELS: Record<SortKey, string> = {\n  updated: \"Last updated\",\n  created: \"Newest\",\n  priority: \"Priority\",\n};\n\ntype StatusFilter = \"all\" | TicketStatus;\ntype PriorityFilter = \"all\" | Priority;\ntype AssigneeFilter = \"all\" | \"unassigned\" | string;\n\nexport function TicketList({ tickets, onOpen, onStatusChange, onPriorityChange, onAssigneeChange, onDelete, onNewTicket }: Props) {\n  const [statusFilter, setStatusFilter] = useState<StatusFilter>(\"all\");\n  const [priorityFilter, setPriorityFilter] = useState<PriorityFilter>(\"all\");\n  const [assigneeFilter, setAssigneeFilter] = useState<AssigneeFilter>(\"all\");\n  const [sortKey, setSortKey] = useState<SortKey>(\"updated\");\n  const [confirmingId, setConfirmingId] = useState<string | null>(null);\n\n  const counts = useMemo(() => {\n    const c: Record<TicketStatus, number> = { open: 0, pending: 0, resolved: 0, closed: 0 };\n    for (const t of tickets) c[t.status] += 1;\n    return c;\n  }, [tickets]);\n\n  const visible = useMemo(() => {\n    let list = tickets;\n    if (statusFilter !== \"all\") list = list.filter((t) => t.status === statusFilter);\n    if (priorityFilter !== \"all\") list = list.filter((t) => t.priority === priorityFilter);\n    if (assigneeFilter === \"unassigned\") list = list.filter((t) => !t.assigneeId);\n    else if (assigneeFilter !== \"all\") list = list.filter((t) => t.assigneeId === assigneeFilter);\n\n    return [...list].sort((a, b) => {\n      if (sortKey === \"created\") return b.createdAt - a.createdAt;\n      if (sortKey === \"priority\") return priorityRank(b.priority) - priorityRank(a.priority);\n      return b.updatedAt - a.updatedAt;\n    });\n  }, [tickets, statusFilter, priorityFilter, assigneeFilter, sortKey]);\n\n  return (\n    <div>\n      <div className=\"mb-5 flex flex-wrap gap-2\">\n        {TICKET_STATUSES.map((status) => (\n          <button\n            key={status}\n            type=\"button\"\n            onClick={() => setStatusFilter(statusFilter === status ? \"all\" : status)}\n            className={`flex items-center gap-1.5 rounded-full border px-3.5 py-1.5 text-xs font-medium capitalize transition-colors ${\n              statusFilter === status\n                ? \"border-blue-600 bg-blue-600 text-white shadow-sm shadow-blue-500/30\"\n                : \"border-slate-200 bg-white text-slate-600 hover:border-blue-200\"\n            }`}\n          >\n            {status}\n            <span\n              className={`rounded-full px-1.5 py-0.5 text-[11px] font-semibold ${\n                statusFilter === status ? \"bg-white/20\" : STATUS_STYLES[status]\n              }`}\n            >\n              {counts[status]}\n            </span>\n          </button>\n        ))}\n      </div>\n\n      <div className=\"mb-4 flex flex-wrap items-center gap-2 text-sm\">\n        <select\n          value={priorityFilter}\n          onChange={(e) => setPriorityFilter(e.target.value as PriorityFilter)}\n          className=\"rounded-lg border border-slate-200 bg-white px-2.5 py-1.5 text-xs capitalize outline-none focus:border-blue-400\"\n        >\n          <option value=\"all\">All priorities</option>\n          {PRIORITIES.map((p) => (\n            <option key={p} value={p}>\n              {p}\n            </option>\n          ))}\n        </select>\n        <select\n          value={assigneeFilter}\n          onChange={(e) => setAssigneeFilter(e.target.value)}\n          className=\"rounded-lg border border-slate-200 bg-white px-2.5 py-1.5 text-xs outline-none focus:border-blue-400\"\n        >\n          <option value=\"all\">All assignees</option>\n          <option value=\"unassigned\">Unassigned</option>\n          {TEAM_MEMBERS.map((m) => (\n            <option key={m.id} value={m.id}>\n              {m.name}\n            </option>\n          ))}\n        </select>\n        <div className=\"ml-auto flex items-center gap-1.5 text-xs text-slate-500\">\n          Sort by\n          <select\n            value={sortKey}\n            onChange={(e) => setSortKey(e.target.value as SortKey)}\n            className=\"rounded-lg border border-slate-200 bg-white px-2.5 py-1.5 text-xs outline-none focus:border-blue-400\"\n          >\n            {SORT_KEYS.map((k) => (\n              <option key={k} value={k}>\n                {SORT_LABELS[k]}\n              </option>\n            ))}\n          </select>\n        </div>\n      </div>\n\n      {visible.length === 0 ? (\n        <div className=\"flex flex-col items-center gap-3 rounded-3xl border border-dashed border-blue-200 bg-white/60 p-12 text-center text-sm text-slate-500 shadow-sm\">\n          <span className=\"flex h-12 w-12 items-center justify-center rounded-full bg-blue-100 text-blue-600\">\n            <Inbox className=\"h-5 w-5\" />\n          </span>\n          {tickets.length === 0 ? (\n            <p>\n              No tickets yet.{\" \"}\n              <button type=\"button\" onClick={onNewTicket} className=\"font-semibold text-slate-900 underline\">\n                Create your first one\n              </button>\n              .\n            </p>\n          ) : (\n            <p>No tickets match these filters.</p>\n          )}\n        </div>\n      ) : (\n        <div className=\"overflow-x-auto rounded-2xl border border-blue-100/70 bg-white shadow-sm shadow-slate-900/[0.03]\">\n          <table className=\"w-full min-w-[760px] text-sm\">\n            <thead className=\"border-b border-slate-200 bg-slate-50 text-left text-xs uppercase text-slate-400\">\n              <tr>\n                <th className=\"px-4 py-2.5 font-medium\">Subject</th>\n                <th className=\"px-4 py-2.5 font-medium\">Priority</th>\n                <th className=\"px-4 py-2.5 font-medium\">Status</th>\n                <th className=\"px-4 py-2.5 font-medium\">Assignee</th>\n                <th className=\"px-4 py-2.5 font-medium\">Updated</th>\n                <th className=\"px-4 py-2.5 font-medium\" />\n              </tr>\n            </thead>\n            <tbody className=\"divide-y divide-slate-100\">\n              {visible.map((t) => (\n                <tr key={t.id} className=\"cursor-pointer hover:bg-slate-50/60\" onClick={() => onOpen(t.id)}>\n                  <td className=\"px-4 py-2.5\">\n                    <p className=\"font-medium text-slate-800\">{t.subject}</p>\n                    <p className=\"text-xs text-slate-500\">\n                      {t.requesterName} · {t.requesterEmail}\n                    </p>\n                  </td>\n                  <td className=\"px-4 py-2.5\" onClick={(e) => e.stopPropagation()}>\n                    <select\n                      value={t.priority}\n                      onChange={(e) => onPriorityChange(t.id, e.target.value as Priority)}\n                      className={`rounded-full border-0 px-2 py-1 text-xs font-medium capitalize outline-none ${PRIORITY_STYLES[t.priority]}`}\n                    >\n                      {PRIORITIES.map((p) => (\n                        <option key={p} value={p}>\n                          {p}\n                        </option>\n                      ))}\n                    </select>\n                  </td>\n                  <td className=\"px-4 py-2.5\" onClick={(e) => e.stopPropagation()}>\n                    <select\n                      value={t.status}\n                      onChange={(e) => onStatusChange(t.id, e.target.value as TicketStatus)}\n                      className={`rounded-full border-0 px-2 py-1 text-xs font-medium capitalize outline-none ${STATUS_STYLES[t.status]}`}\n                    >\n                      {TICKET_STATUSES.map((s) => (\n                        <option key={s} value={s}>\n                          {s}\n                        </option>\n                      ))}\n                    </select>\n                  </td>\n                  <td className=\"px-4 py-2.5\" onClick={(e) => e.stopPropagation()}>\n                    <select\n                      value={t.assigneeId ?? \"\"}\n                      onChange={(e) => onAssigneeChange(t.id, e.target.value || null)}\n                      className=\"rounded-lg border border-slate-200 bg-white px-2 py-1 text-xs outline-none focus:border-blue-400\"\n                    >\n                      <option value=\"\">Unassigned</option>\n                      {TEAM_MEMBERS.map((m) => (\n                        <option key={m.id} value={m.id}>\n                          {m.name}\n                        </option>\n                      ))}\n                    </select>\n                  </td>\n                  <td className=\"px-4 py-2.5 text-xs text-slate-500\">{formatDateTime(t.updatedAt)}</td>\n                  <td className=\"px-4 py-2.5\" onClick={(e) => e.stopPropagation()}>\n                    {confirmingId === t.id ? (\n                      <div className=\"flex items-center justify-end gap-1.5\">\n                        <button\n                          type=\"button\"\n                          onClick={() => {\n                            onDelete(t.id);\n                            setConfirmingId(null);\n                          }}\n                          className=\"text-xs font-medium text-red-600\"\n                        >\n                          Delete\n                        </button>\n                        <button type=\"button\" onClick={() => setConfirmingId(null)} className=\"text-xs text-slate-400\">\n                          Cancel\n                        </button>\n                      </div>\n                    ) : (\n                      <div className=\"flex items-center justify-end text-slate-400\">\n                        <button\n                          type=\"button\"\n                          title=\"Delete\"\n                          onClick={() => setConfirmingId(t.id)}\n                          className=\"rounded p-1 hover:bg-red-50 hover:text-red-600\"\n                        >\n                          <Trash2 className=\"h-3.5 w-3.5\" />\n                        </button>\n                      </div>\n                    )}\n                  </td>\n                </tr>\n              ))}\n            </tbody>\n          </table>\n        </div>\n      )}\n      <p className=\"mt-2 text-xs text-slate-400\">\n        Demo data ships with this template (see README) — everything here is editable and deletable.\n      </p>\n    </div>\n  );\n}\n",
  "src/index.css": "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\nhtml {\n  -webkit-font-smoothing: antialiased;\n}\n\nbody {\n  font-family: \"Inter\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n}\n\n::-webkit-scrollbar {\n  height: 8px;\n  width: 8px;\n}\n\n::-webkit-scrollbar-thumb {\n  background-color: rgba(0, 0, 0, 0.15);\n  border-radius: 9999px;\n}\n",
  "src/lib/seedData.ts": "import type { CannedReply, Ticket } from \"../types\";\n\n// ---------------------------------------------------------------------------\n// DEMO DATA ONLY. This file exists so the ticket queue isn't empty the very\n// first time you open the app — every name, email, and message below is\n// fake. It's loaded once by lib/storage.ts (only when localStorage has\n// never held tickets/replies before) and after that behaves exactly like\n// anything you type in yourself: fully editable and deletable, and it will\n// NOT come back once you clear it out.\n// ---------------------------------------------------------------------------\n\nconst HOUR = 60 * 60 * 1000;\nconst DAY = 24 * HOUR;\n\nfunction ago(ms: number): number {\n  return Date.now() - ms;\n}\n\nexport function seedTickets(): Ticket[] {\n  return [\n    {\n      id: \"seed-1\",\n      subject: \"Can't log into my account\",\n      requesterName: \"Elena Ward\",\n      requesterEmail: \"elena.ward@northfield.io\",\n      priority: \"urgent\",\n      status: \"open\",\n      assigneeId: \"priya\",\n      createdAt: ago(3 * HOUR),\n      updatedAt: ago(20 * 60 * 1000),\n      messages: [\n        {\n          id: \"seed-1-m1\",\n          fromCustomer: true,\n          authorName: \"Elena Ward\",\n          body: \"I've tried resetting my password three times and I still can't get past the login screen — it just spins forever.\",\n          createdAt: ago(3 * HOUR),\n        },\n        {\n          id: \"seed-1-m2\",\n          fromCustomer: false,\n          authorName: \"Priya Nair\",\n          body: \"Sorry about that, Elena! Can you tell me which browser you're using, and whether you see any error message flash by before it spins?\",\n          createdAt: ago(20 * 60 * 1000),\n        },\n      ],\n    },\n    {\n      id: \"seed-2\",\n      subject: \"Billing charged twice this month\",\n      requesterName: \"Marcus Delgado\",\n      requesterEmail: \"marcus.d@brightloop.co\",\n      priority: \"high\",\n      status: \"pending\",\n      assigneeId: \"marcus\",\n      createdAt: ago(1 * DAY + 2 * HOUR),\n      updatedAt: ago(5 * HOUR),\n      messages: [\n        {\n          id: \"seed-2-m1\",\n          fromCustomer: true,\n          authorName: \"Marcus Delgado\",\n          body: \"My card was charged twice on the 3rd, both for the Pro plan. Can you refund the duplicate?\",\n          createdAt: ago(1 * DAY + 2 * HOUR),\n        },\n        {\n          id: \"seed-2-m2\",\n          fromCustomer: false,\n          authorName: \"Marcus Chen\",\n          body: \"Thanks for flagging this — I can see both charges on our end. I've kicked off a refund for the duplicate; it should land back on your card within 5-7 business days.\",\n          createdAt: ago(1 * DAY),\n        },\n        {\n          id: \"seed-2-m3\",\n          fromCustomer: true,\n          authorName: \"Marcus Delgado\",\n          body: \"Appreciate the quick turnaround. I'll keep an eye out for it.\",\n          createdAt: ago(5 * HOUR),\n        },\n      ],\n    },\n    {\n      id: \"seed-3\",\n      subject: \"How do I export my data?\",\n      requesterName: \"Priya Subramaniam\",\n      requesterEmail: \"priya.s@fernwoodlabs.com\",\n      priority: \"medium\",\n      status: \"resolved\",\n      assigneeId: \"sofia\",\n      createdAt: ago(4 * DAY),\n      updatedAt: ago(3 * DAY),\n      messages: [\n        {\n          id: \"seed-3-m1\",\n          fromCustomer: true,\n          authorName: \"Priya Subramaniam\",\n          body: \"Is there a way to export everything as CSV before we switch plans?\",\n          createdAt: ago(4 * DAY),\n        },\n        {\n          id: \"seed-3-m2\",\n          fromCustomer: false,\n          authorName: \"Sofia Rossi\",\n          body: \"Yes! Head to Settings > Data > Export and choose CSV — you'll get an email with a download link within a few minutes. Let me know if it doesn't show up.\",\n          createdAt: ago(3 * DAY + 12 * HOUR),\n        },\n        {\n          id: \"seed-3-m3\",\n          fromCustomer: true,\n          authorName: \"Priya Subramaniam\",\n          body: \"Got it, worked perfectly. Thank you!\",\n          createdAt: ago(3 * DAY),\n        },\n      ],\n    },\n    {\n      id: \"seed-4\",\n      subject: \"App crashes when uploading a large file\",\n      requesterName: \"Owen Fischer\",\n      requesterEmail: \"owen@fischerstudio.design\",\n      priority: \"high\",\n      status: \"open\",\n      assigneeId: \"devon\",\n      createdAt: ago(6 * HOUR),\n      updatedAt: ago(6 * HOUR),\n      messages: [\n        {\n          id: \"seed-4-m1\",\n          fromCustomer: true,\n          authorName: \"Owen Fischer\",\n          body: \"Uploading anything over ~200MB crashes the tab entirely. Happens every time, on both Chrome and Firefox.\",\n          createdAt: ago(6 * HOUR),\n        },\n      ],\n    },\n    {\n      id: \"seed-5\",\n      subject: \"Feature request: dark mode\",\n      requesterName: \"Aisha Patel\",\n      requesterEmail: \"aisha.patel@loopgrid.dev\",\n      priority: \"low\",\n      status: \"open\",\n      assigneeId: null,\n      createdAt: ago(2 * DAY),\n      updatedAt: ago(2 * DAY),\n      messages: [\n        {\n          id: \"seed-5-m1\",\n          fromCustomer: true,\n          authorName: \"Aisha Patel\",\n          body: \"Would love a dark mode option — my whole team works late and the bright white background is rough at night.\",\n          createdAt: ago(2 * DAY),\n        },\n      ],\n    },\n    {\n      id: \"seed-6\",\n      subject: \"Refund request for annual plan\",\n      requesterName: \"Grace Liu\",\n      requesterEmail: \"grace.liu@meridianworks.com\",\n      priority: \"urgent\",\n      status: \"pending\",\n      assigneeId: \"priya\",\n      createdAt: ago(30 * 60 * 1000),\n      updatedAt: ago(10 * 60 * 1000),\n      messages: [\n        {\n          id: \"seed-6-m1\",\n          fromCustomer: true,\n          authorName: \"Grace Liu\",\n          body: \"We accidentally renewed the annual plan instead of switching to monthly. Can we get this refunded and moved to monthly billing?\",\n          createdAt: ago(30 * 60 * 1000),\n        },\n        {\n          id: \"seed-6-m2\",\n          fromCustomer: false,\n          authorName: \"Priya Nair\",\n          body: \"I can help with that — give me a few minutes to pull up the account and confirm the renewal date.\",\n          createdAt: ago(10 * 60 * 1000),\n        },\n      ],\n    },\n    {\n      id: \"seed-7\",\n      subject: \"Question about seat limits on the Team plan\",\n      requesterName: \"Noah Bennett\",\n      requesterEmail: \"noah.b@harborvane.io\",\n      priority: \"medium\",\n      status: \"closed\",\n      assigneeId: \"sofia\",\n      createdAt: ago(8 * DAY),\n      updatedAt: ago(7 * DAY),\n      messages: [\n        {\n          id: \"seed-7-m1\",\n          fromCustomer: true,\n          authorName: \"Noah Bennett\",\n          body: \"Does the Team plan cap out at 10 seats, or can we add more as we grow?\",\n          createdAt: ago(8 * DAY),\n        },\n        {\n          id: \"seed-7-m2\",\n          fromCustomer: false,\n          authorName: \"Sofia Rossi\",\n          body: \"You can add seats beyond 10 any time — they're billed pro-rata for the rest of your cycle. No hard cap on Team.\",\n          createdAt: ago(7 * DAY + 6 * HOUR),\n        },\n        {\n          id: \"seed-7-m3\",\n          fromCustomer: true,\n          authorName: \"Noah Bennett\",\n          body: \"Perfect, that answers it. Thanks!\",\n          createdAt: ago(7 * DAY),\n        },\n      ],\n    },\n  ];\n}\n\nexport function seedCannedReplies(): CannedReply[] {\n  return [\n    {\n      id: \"seed-c1\",\n      title: \"Thanks for reaching out\",\n      body: \"Hi there — thanks for reaching out! I'm looking into this now and will follow up shortly.\",\n    },\n    {\n      id: \"seed-c2\",\n      title: \"Requesting more info\",\n      body: \"Could you share a few more details — what browser/device you're using, and any error messages you're seeing? That'll help me track this down faster.\",\n    },\n    {\n      id: \"seed-c3\",\n      title: \"Issue resolved\",\n      body: \"Glad we got that sorted! I'm marking this ticket as resolved — feel free to reply if it comes up again.\",\n    },\n    {\n      id: \"seed-c4\",\n      title: \"Escalating internally\",\n      body: \"This needs a closer look from our engineering team, so I'm escalating it internally. I'll update you as soon as I hear back.\",\n    },\n    {\n      id: \"seed-c5\",\n      title: \"Refund processed\",\n      body: \"Your refund has been processed and should appear on your original payment method within 5-7 business days. Let me know if it doesn't show up by then.\",\n    },\n  ];\n}\n",
  "src/lib/storage.ts": "import type { CannedReply, Message, Priority, Ticket, TicketStatus } from \"../types\";\nimport { PRIORITIES, TICKET_STATUSES } from \"../types\";\nimport { seedCannedReplies, seedTickets } from \"./seedData\";\n\nconst TICKETS_KEY = \"support-desk:tickets\";\nconst CANNED_KEY = \"support-desk:cannedReplies\";\n\nfunction isPriority(value: unknown): value is Priority {\n  return typeof value === \"string\" && PRIORITIES.includes(value as Priority);\n}\n\nfunction isStatus(value: unknown): value is TicketStatus {\n  return typeof value === \"string\" && TICKET_STATUSES.includes(value as TicketStatus);\n}\n\nfunction isMessage(value: unknown): value is Message {\n  if (!value || typeof value !== \"object\") return false;\n  const m = value as Record<string, unknown>;\n  return (\n    typeof m.id === \"string\" &&\n    typeof m.body === \"string\" &&\n    typeof m.authorName === \"string\" &&\n    typeof m.fromCustomer === \"boolean\" &&\n    typeof m.createdAt === \"number\"\n  );\n}\n\nfunction isTicket(value: unknown): value is Ticket {\n  if (!value || typeof value !== \"object\") return false;\n  const t = value as Record<string, unknown>;\n  return (\n    typeof t.id === \"string\" &&\n    typeof t.subject === \"string\" &&\n    typeof t.requesterName === \"string\" &&\n    typeof t.requesterEmail === \"string\" &&\n    isPriority(t.priority) &&\n    isStatus(t.status) &&\n    (t.assigneeId === null || typeof t.assigneeId === \"string\") &&\n    Array.isArray(t.messages) &&\n    typeof t.createdAt === \"number\" &&\n    typeof t.updatedAt === \"number\"\n  );\n}\n\nfunction isCannedReply(value: unknown): value is CannedReply {\n  if (!value || typeof value !== \"object\") return false;\n  const c = value as Record<string, unknown>;\n  return typeof c.id === \"string\" && typeof c.title === \"string\" && typeof c.body === \"string\";\n}\n\nexport function loadTickets(): Ticket[] {\n  try {\n    const raw = localStorage.getItem(TICKETS_KEY);\n    if (raw === null) {\n      // Never saved before — seed demo tickets so the queue isn't empty on\n      // first load. See src/lib/seedData.ts: this is fake data, and once\n      // you clear it out (saveTickets persists the empty array) it will\n      // not be re-seeded.\n      const seeded = seedTickets();\n      saveTickets(seeded);\n      return seeded;\n    }\n    const parsed = JSON.parse(raw);\n    if (!Array.isArray(parsed)) return [];\n    return parsed.filter(isTicket).map((t) => ({ ...t, messages: t.messages.filter(isMessage) }));\n  } catch {\n    return [];\n  }\n}\n\nexport function saveTickets(tickets: Ticket[]): void {\n  try {\n    localStorage.setItem(TICKETS_KEY, JSON.stringify(tickets));\n  } catch {\n    // Storage full or unavailable — in-memory state still works this session.\n  }\n}\n\nexport function loadCannedReplies(): CannedReply[] {\n  try {\n    const raw = localStorage.getItem(CANNED_KEY);\n    if (raw === null) {\n      const seeded = seedCannedReplies();\n      saveCannedReplies(seeded);\n      return seeded;\n    }\n    const parsed = JSON.parse(raw);\n    return Array.isArray(parsed) ? parsed.filter(isCannedReply) : [];\n  } catch {\n    return [];\n  }\n}\n\nexport function saveCannedReplies(replies: CannedReply[]): void {\n  try {\n    localStorage.setItem(CANNED_KEY, JSON.stringify(replies));\n  } catch {\n    // Ignore — see saveTickets.\n  }\n}\n",
  "src/main.tsx": "import React from \"react\";\nimport ReactDOM from \"react-dom/client\";\nimport App from \"./App\";\nimport \"./index.css\";\n\nReactDOM.createRoot(document.getElementById(\"root\")!).render(\n  <React.StrictMode>\n    <App />\n  </React.StrictMode>\n);\n",
  "src/types.ts": "export type Priority = \"low\" | \"medium\" | \"high\" | \"urgent\";\n\nexport const PRIORITIES: Priority[] = [\"low\", \"medium\", \"high\", \"urgent\"];\n\nexport type TicketStatus = \"open\" | \"pending\" | \"resolved\" | \"closed\";\n\nexport const TICKET_STATUSES: TicketStatus[] = [\"open\", \"pending\", \"resolved\", \"closed\"];\n\nexport interface TeamMember {\n  id: string;\n  name: string;\n}\n\n// A small fixed roster — this demo doesn't manage staff accounts, it just\n// lets you assign tickets to whoever's on the team.\nexport const TEAM_MEMBERS: TeamMember[] = [\n  { id: \"priya\", name: \"Priya Nair\" },\n  { id: \"marcus\", name: \"Marcus Chen\" },\n  { id: \"sofia\", name: \"Sofia Rossi\" },\n  { id: \"devon\", name: \"Devon Blake\" },\n];\n\nexport function teamMemberName(id: string | null): string {\n  if (!id) return \"Unassigned\";\n  return TEAM_MEMBERS.find((m) => m.id === id)?.name ?? \"Unassigned\";\n}\n\nexport interface Message {\n  id: string;\n  body: string;\n  authorName: string;\n  fromCustomer: boolean;\n  createdAt: number;\n}\n\nexport interface Ticket {\n  id: string;\n  subject: string;\n  requesterName: string;\n  requesterEmail: string;\n  priority: Priority;\n  status: TicketStatus;\n  assigneeId: string | null;\n  messages: Message[];\n  createdAt: number;\n  updatedAt: number;\n}\n\nexport interface CannedReply {\n  id: string;\n  title: string;\n  body: string;\n}\n\nexport type SortKey = \"updated\" | \"created\" | \"priority\";\n\nexport const SORT_KEYS: SortKey[] = [\"updated\", \"created\", \"priority\"];\n\nconst PRIORITY_RANK: Record<Priority, number> = { urgent: 3, high: 2, medium: 1, low: 0 };\n\nexport function priorityRank(p: Priority): number {\n  return PRIORITY_RANK[p];\n}\n\nexport function formatDateTime(ms: number): string {\n  return new Date(ms).toLocaleString(undefined, {\n    month: \"short\",\n    day: \"numeric\",\n    hour: \"numeric\",\n    minute: \"2-digit\",\n  });\n}\n",
  "tailwind.config.js": "/** @type {import('tailwindcss').Config} */\nexport default {\n  content: [\"./index.html\", \"./src/**/*.{js,ts,jsx,tsx}\"],\n  theme: {\n    extend: {},\n  },\n  plugins: [],\n};\n",
  "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"useDefineForClassFields\": true,\n    \"lib\": [\"ES2020\", \"DOM\", \"DOM.Iterable\"],\n    \"module\": \"ESNext\",\n    \"skipLibCheck\": true,\n    \"moduleResolution\": \"bundler\",\n    \"allowImportingTsExtensions\": true,\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"noEmit\": true,\n    \"jsx\": \"react-jsx\",\n    \"strict\": true,\n    \"noUnusedLocals\": true,\n    \"noUnusedParameters\": true,\n    \"noFallthroughCasesInSwitch\": true\n  },\n  \"include\": [\"src\"],\n  \"references\": [{ \"path\": \"./tsconfig.node.json\" }]\n}\n",
  "tsconfig.node.json": "{\n  \"compilerOptions\": {\n    \"composite\": true,\n    \"skipLibCheck\": true,\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"allowSyntheticDefaultImports\": true,\n    \"strict\": true\n  },\n  \"include\": [\"vite.config.ts\"]\n}\n",
  "vite.config.ts": "import { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\nexport default defineConfig({\n  plugins: [react()],\n});\n",
};
